changeSet.sql:

-- Step 1: Clean up existing CREDIT-level blocking reasons to establish clean baseline
-- Delete existing credit blocking reasons and related data
DELETE FROM m_credit_blocking_reason;
UPDATE m_loan SET block_status_id = NULL;
DELETE FROM m_blocking_reason_setting WHERE level = 'CREDIT';

-- Step 2: Add baseline blocking reasons for credits as specified in EA-153 task -- These are the 5 blocking reasons required for the baseline: -- 1. Fallecimiento (Death) - Priority 1 -- 2. Acelerado - Cobro Juridico (Accelerated - Legal Collection) - Priority 2 -- 3. Acelerado (Accelerated) - Priority 3 -- 4. Castigo - Fraude (Punishment - Fraud) - Priority 4 -- 5. Castigo (Punishment) - Priority 5
INSERT INTO m_blocking_reason_setting (priority, description, name_of_reason, "level", is_enabled) VALUES(1, 'Fallecimiento', 'Fallecimiento', 'CREDIT', 1);
INSERT INTO m_blocking_reason_setting (priority, description, name_of_reason, "level", is_enabled) VALUES(2, 'Acelerado - Cobro Juridico', 'Acelerado - Cobro Juridico', 'CREDIT', 1);
INSERT INTO m_blocking_reason_setting (priority, description, name_of_reason, "level", is_enabled) VALUES(3, 'Acelerado', 'Acelerado', 'CREDIT', 1);
INSERT INTO m_blocking_reason_setting (priority, description, name_of_reason, "level", is_enabled) VALUES(4, 'Castigo - Fraude', 'Castigo - Fraude', 'CREDIT', 1);
INSERT INTO m_blocking_reason_setting (priority, description, name_of_reason, "level", is_enabled) VALUES(5, 'Castigo', 'Castigo', 'CREDIT', 1);
